/*
 * ============================================================================
 *  DINO RUNNER  -  a Chrome-style Dinosaur Runner written in C with Raylib
 * ============================================================================
 *
 *  Everything (graphics AND sound) is generated by code, so there are no
 *  image or audio files to lose. The whole game lives in this one file.
 *
 *  HOW THE FILE IS ORGANISED (search for the big banner comments):
 *    1. Constants and data types
 *    2. Global variables
 *    3. Small helper functions (colours, text, saving)
 *    4. Audio  (sound effects + music generated from maths)
 *    5. Particles
 *    6. Dinosaur (drawing, physics, hitboxes)
 *    7. Obstacles (cacti and birds)
 *    8. World (sky, clouds, dunes, ground, day/night)
 *    9. User interface (buttons, HUD, menus)
 *   10. Game states and the main loop
 *
 *  CONTROLS
 *    SPACE / UP / W ... jump        DOWN / S ... duck (or fast-fall)
 *    P ................ pause       M ........... sound on/off
 *    F or F11 ......... fullscreen  ESC ......... pause / back / quit
 * ============================================================================
 */

#include "raylib.h"

#include <stdbool.h>

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

