/* The game is drawn on a small "virtual" screen of 800x300 pixels and then
   scaled up to fit the real window. That way the game looks the same at any
   window size or in fullscreen. */
#define VIRTUAL_W 800
#define VIRTUAL_H 300

#define GROUND_Y 230          /* y position of the ground line (dino's feet)  */
#define DINO_X 70             /* the dino always stays at this x position     */
#define PIXEL 2               /* size of one "art pixel" of the dino sprite   */

#define GRAVITY 2400.0f       /* downward acceleration (pixels / second^2)    */
#define JUMP_VELOCITY 760.0f  /* upward speed at the moment of a jump         */
#define JUMP_CUT_VELOCITY 300.0f /* releasing jump early caps the rise speed  */
#define FAST_FALL_FACTOR 2.6f /* gravity multiplier while holding DOWN in air */

#define START_SPEED 300.0f    /* ground speed at the start (pixels / second)  */
#define MAX_SPEED 700.0f
#define BIRD_EXTRA_SPEED 40.0f
#define NIGHT_INTERVAL 600    /* day <-> night switch every 600 points        */

#define MAX_OBSTACLES 8
#define MAX_CLOUDS 6
#define MAX_STARS 50
#define MAX_PARTICLES 200
#define MAX_DECOR 14
#define MAX_SPECKS 70

#define SAMPLE_RATE 22050     /* audio samples per second for generated sound */
#define SAVE_FILE_NAME "dino_save.dat"

typedef enum {
    STATE_MENU,
    STATE_PLAYING,
    STATE_PAUSED,
    STATE_GAMEOVER,
    STATE_SETTINGS
} GameState;

typedef enum { TRANS_NONE, TRANS_OUT, TRANS_IN } TransitionPhase;

typedef enum { OBST_CACTUS_SMALL, OBST_CACTUS_LARGE, OBST_BIRD } ObstacleType;

/* The dinosaur. "y" is the position of its FEET (not its head). */
typedef struct {
    float y;
    float velY;
    bool onGround;
    bool ducking;
    bool alive;
    float runTimer;
    int frame;                /* 0 or 1: which running animation frame        */
} Dino;

/* One cactus group or one bird. "active" false means the slot is free. */
typedef struct {
    bool active;
    ObstacleType type;
    int count;                /* number of cacti in the group                 */
    float x, y;               /* top-left corner                              */
    float w, h;               /* total size                                   */
    float animTimer;
    int frame;
} Obstacle;

typedef struct { float x, y, speed, scale; } Cloud;
typedef struct { float x, y, phase; int size; } Star;
typedef struct { float x; int y; int w; } Speck;
typedef struct { float x; int type; int yOffset; } Decor;

typedef struct {
    bool active;
    float x, y, vx, vy;
    float life, maxLife;
    float size;
    Color color;
} Particle;

/* Things the player can change. Saved to disk together with the best score. */
typedef struct {
    bool soundOn;
    int musicVolume;          /* 0..10 */
    int sfxVolume;            /* 0..10 */
    int best;                 /* best score */
} Settings;

