/* ========================================================================== */
/* 3. SMALL HELPER FUNCTIONS                                                  */
/* ========================================================================== */

static float ClampFloat(float v, float lo, float hi)
{
    return (v < lo) ? lo : (v > hi) ? hi : v;
}

static int ClampInt(int v, int lo, int hi)
{
    return (v < lo) ? lo : (v > hi) ? hi : v;
}

/* Blend colour a into colour b. t = 0 gives a, t = 1 gives b. */
static Color LerpColor(Color a, Color b, float t)
{
    Color c;
    c.r = (unsigned char)(a.r + (b.r - a.r) * t);
    c.g = (unsigned char)(a.g + (b.g - a.g) * t);
    c.b = (unsigned char)(a.b + (b.b - a.b) * t);
    c.a = (unsigned char)(a.a + (b.a - a.a) * t);
    return c;
}

/* Pick the day or night version of a colour depending on the time of day. */
static Color Tint(Color day, Color night)
{
    return LerpColor(day, night, nightFactor);
}

/* Draw a filled rectangle snapped to whole pixels (keeps the pixel-art crisp). */
static void FillRect(float x, float y, float w, float h, Color c)
{
    DrawRectangleRec((Rectangle){roundf(x), roundf(y), roundf(w), roundf(h)}, c);
}

static void DrawTextCentered(const char *text, int centerX, int y, int size, Color c)
{
    DrawText(text, centerX - MeasureText(text, size) / 2, y, size, c);
}

/* Text with a dark drop shadow so it is readable on any background. */
static void DrawTextShadowCentered(const char *text, int centerX, int y, int size, Color c, float alpha)
{
    DrawTextCentered(text, centerX + 2, y + 2, size, Fade((Color){0, 0, 0, 255}, 0.55f * alpha));
    DrawTextCentered(text, centerX, y, size, Fade(c, alpha));
}

/* Converts a mouse position in the real window into virtual-screen coordinates. */
static Vector2 GetVirtualMouse(void)
{
    Vector2 m = GetMousePosition();
    return (Vector2){(m.x - viewOffsetX) / viewScale, (m.y - viewOffsetY) / viewScale};
}

/* ---- Saving and loading (a tiny text file next to the .exe) ---- */

static void SaveGameData(void)
{
    FILE *f = fopen(saveFilePath, "w");
    if (f == NULL) return; /* if saving fails the game still works */
    fprintf(f, "%d %d %d %d\n", settings.best, settings.soundOn ? 1 : 0,
            settings.musicVolume, settings.sfxVolume);
    fclose(f);
}

static void LoadGameData(void)
{
    FILE *f = fopen(saveFilePath, "r");
    if (f == NULL) return; /* first run: no save file yet */
    int best, sound, music, sfx;
    if (fscanf(f, "%d %d %d %d", &best, &sound, &music, &sfx) == 4) {
        settings.best = (best < 0) ? 0 : best;
        settings.soundOn = (sound != 0);
        settings.musicVolume = ClampInt(music, 0, 10);
        settings.sfxVolume = ClampInt(sfx, 0, 10);
    }
    fclose(f);
}

/* ========================================================================== */
/* 4. AUDIO  (all sounds are generated by code)                               */
/* ========================================================================== */

/* Allocate an empty buffer of 16-bit samples (silence). */
static short *CreateBuffer(int count)
{
    return (short *)calloc((size_t)count, sizeof(short));
}

/* Add a sample value to the buffer, preventing numbers that are too loud. */
static void MixSample(short *buffer, int index, float value)
{
    float mixed = buffer[index] / 32767.0f + value;
    buffer[index] = (short)(ClampFloat(mixed, -1.0f, 1.0f) * 32000.0f);
}

/* Square-wave beep that glides from freqStart to freqEnd and fades out. */
static void AddTone(short *buffer, int bufferLen, int start, int len,
                    float freqStart, float freqEnd, float amplitude)
{
    float phase = 0.0f;
    for (int i = 0; i < len && start + i < bufferLen; i++) {
        float t = (float)i / (float)len;
        float freq = freqStart + (freqEnd - freqStart) * t;
        phase += freq / SAMPLE_RATE;
        float wave = (fmodf(phase, 1.0f) < 0.5f) ? 1.0f : -1.0f;
        MixSample(buffer, start + i, wave * amplitude * (1.0f - t));
    }
}

/* Burst of noise (used for the crash and the music's hi-hat). */
static void AddNoise(short *buffer, int bufferLen, int start, int len, float amplitude)
{
    for (int i = 0; i < len && start + i < bufferLen; i++) {
        float t = (float)i / (float)len;
        float noise = ((float)rand() / (float)RAND_MAX) * 2.0f - 1.0f;
        MixSample(buffer, start + i, noise * amplitude * (1.0f - t) * (1.0f - t));
    }
}

/* Turn a buffer of samples into a Raylib Sound. LoadSoundFromWave copies the
   data, so we can free our buffer right afterwards (no memory leak). */
static Sound BuildSound(short *samples, int count)
{
    Sound sound = {0};
    if (samples == NULL) return sound;
    Wave wave = {0};
    wave.frameCount = (unsigned int)count;
    wave.sampleRate = SAMPLE_RATE;
    wave.sampleSize = 16;
    wave.channels = 1;
    wave.data = samples;
    sound = LoadSoundFromWave(wave);
    free(samples);
    return sound;
}

static float MidiToFrequency(int note)
{
    return 440.0f * powf(2.0f, (float)(note - 69) / 12.0f);
}

/* Builds a 64-step chiptune loop: arpeggio lead + bass + hi-hat. */
static Sound BuildMusic(void)
{
    const float bpm = 132.0f;
    const int stepSamples = (int)(60.0f / bpm / 2.0f * SAMPLE_RATE); /* eighth note */
    const int steps = 64;
    const int total = stepSamples * steps;

    /* Four chords (Am, F, C, G), three notes each, as MIDI note numbers. */
    static const int chords[4][3] = {{57, 60, 64}, {53, 57, 60}, {60, 64, 67}, {55, 59, 62}};
    static const int bassRoot[4] = {45, 41, 48, 43};
    static const int pattern[8] = {0, 1, 2, 1, 0, 1, 2, 2};

    short *buf = CreateBuffer(total);
    if (buf == NULL) return (Sound){0};

    for (int i = 0; i < total; i++) {
        int step = i / stepSamples;
        float tt = (float)(i % stepSamples) / SAMPLE_RATE;
        int bar = (step / 8) % 4;
        int posInBar = step % 8;
        int octave = ((step / 32) % 2 == 1) ? 12 : 0; /* second half plays higher */

        /* Lead: pulse wave arpeggio with a quick fade for each note. */
        float leadFreq = MidiToFrequency(chords[bar][pattern[posInBar]] + octave);
        float leadPhase = fmodf(leadFreq * tt, 1.0f);
        float lead = (leadPhase < 0.25f) ? 1.0f : -1.0f;
        float leadEnv = 1.0f - (tt / 0.2273f) * 0.75f;
        float sample = lead * 0.10f * leadEnv;

        /* Bass: triangle wave, a new note every half bar (4 steps). */
        int halfBar = step / 4;
        float bassTime = (float)(i - halfBar * 4 * stepSamples) / SAMPLE_RATE;
        float bassPhase = fmodf(MidiToFrequency(bassRoot[bar]) * bassTime, 1.0f);
        float triangle = 4.0f * fabsf(bassPhase - 0.5f) - 1.0f;
        sample += triangle * 0.20f * (1.0f - bassTime / 1.0f * 0.5f);

        MixSample(buf, i, sample);
    }

    /* Hi-hat on every off-beat step. */
    for (int step = 1; step < steps; step += 2)
        AddNoise(buf, total, step * stepSamples, SAMPLE_RATE / 40, 0.07f);

    return BuildSound(buf, total);
}

static void GenerateAudio(void)
{
    int n;
    short *b;

    n = (int)(0.18f * SAMPLE_RATE);                       /* jump: rising beep */
    b = CreateBuffer(n);
    if (b) AddTone(b, n, 0, n, 320.0f, 760.0f, 0.35f);
    sfxJump = BuildSound(b, n);

    n = (int)(0.45f * SAMPLE_RATE);                       /* crash: noise + low drop */
    b = CreateBuffer(n);
    if (b) {
        AddNoise(b, n, 0, n, 0.45f);
        AddTone(b, n, 0, n, 160.0f, 40.0f, 0.40f);
    }
    sfxHit = BuildSound(b, n);

    n = (int)(0.24f * SAMPLE_RATE);                       /* milestone: two quick notes */
    b = CreateBuffer(n);
    if (b) {
        AddTone(b, n, 0, n / 2, 880.0f, 880.0f, 0.30f);
        AddTone(b, n, n / 2, n / 2, 1320.0f, 1320.0f, 0.30f);
    }
    sfxMilestone = BuildSound(b, n);

    n = (int)(0.07f * SAMPLE_RATE);                       /* button click */
    b = CreateBuffer(n);
    if (b) AddTone(b, n, 0, n, 660.0f, 900.0f, 0.30f);
    sfxClick = BuildSound(b, n);

    musicLoop = BuildMusic();
}

static void ApplyAudioVolumes(void)
{
    if (!audioReady) return;
    float sfx = settings.sfxVolume / 10.0f;
    SetSoundVolume(sfxJump, sfx);
    SetSoundVolume(sfxHit, sfx);
    SetSoundVolume(sfxMilestone, sfx);
    SetSoundVolume(sfxClick, sfx);
    SetSoundVolume(musicLoop, settings.musicVolume / 10.0f);
}

static void PlaySfx(Sound s)
{
    if (audioReady && settings.soundOn && s.frameCount > 0) PlaySound(s);
}

/* Called every frame: keeps the background music looping when it should play. */
static void UpdateMusic(void)
{
    if (!audioReady || musicLoop.frameCount == 0) return;
    bool wanted = settings.soundOn && settings.musicVolume > 0 &&
                  (gameState == STATE_MENU || gameState == STATE_SETTINGS ||
                   gameState == STATE_PLAYING);
    if (wanted && !IsSoundPlaying(musicLoop)) PlaySound(musicLoop);
    if (!wanted && IsSoundPlaying(musicLoop)) StopSound(musicLoop);
}

/* ========================================================================== */
/* 5. PARTICLES                                                               */
/* ========================================================================== */

static void SpawnParticles(float x, float y, int count, Color color, float speed, float upward, float size)
{
    for (int n = 0; n < count; n++) {
        for (int i = 0; i < MAX_PARTICLES; i++) {
            if (particles[i].active) continue;
            Particle *p = &particles[i];
            p->active = true;
            p->x = x;
            p->y = y;
            p->vx = (GetRandomValue(-100, 100) / 100.0f) * speed;
            p->vy = -(GetRandomValue(0, 100) / 100.0f) * speed * upward;
            p->maxLife = 0.3f + GetRandomValue(0, 40) / 100.0f;
            p->life = p->maxLife;
            p->size = size + (float)GetRandomValue(0, 2);
            p->color = color;
            break;
        }
    }
}

static void UpdateParticles(float dt)
{
    for (int i = 0; i < MAX_PARTICLES; i++) {
        Particle *p = &particles[i];
        if (!p->active) continue;
        p->vy += 700.0f * dt;     /* particles fall back down */
        p->x += p->vx * dt;
        p->y += p->vy * dt;
        p->life -= dt;
        if (p->life <= 0.0f) p->active = false;
    }
}

static void DrawParticles(void)
{
    for (int i = 0; i < MAX_PARTICLES; i++) {
        const Particle *p = &particles[i];
        if (!p->active) continue;
        FillRect(p->x, p->y, p->size, p->size, Fade(p->color, p->life / p->maxLife));
    }
}

static Color DustColor(void)
{
    return Tint((Color){205, 170, 120, 255}, (Color){130, 120, 160, 255});
}

/* ========================================================================== */
/* 6. THE DINOSAUR                                                            */
/* ========================================================================== */

static void DrawPixelRects(const PixelRect *rects, int count, float ox, float oy, Color c)
{
    for (int i = 0; i < count; i++)
        FillRect(ox + rects[i].x * PIXEL, oy + rects[i].y * PIXEL,
                 rects[i].w * PIXEL, rects[i].h * PIXEL, c);
}

static void DrawOnePixelRect(PixelRect r, float ox, float oy, Color c)
{
    DrawPixelRects(&r, 1, ox, oy, c);
}

/* Draws the dino. (x, feetY) is the point where its feet touch the ground. */
static void DrawDino(float x, float feetY, bool ducking, bool onGround, bool alive, int frame)
{
    Color bodyColor = Tint((Color){60, 60, 75, 255}, (Color){235, 235, 245, 255});
    Color eyeColor = alive ? Tint((Color){255, 255, 255, 255}, (Color){30, 30, 60, 255})
                           : (Color){230, 40, 40, 255};
    bool legsStep = onGround && alive;

    if (ducking) {
        float oy = feetY - 10 * PIXEL;
        DrawPixelRects(DUCK_BODY, 4, x, oy, bodyColor);
        if (legsStep && frame == 1) {
            DrawOnePixelRect(DUCK_LEG_L_UP, x, oy, bodyColor);
            DrawOnePixelRect(DUCK_LEG_R_DOWN, x, oy, bodyColor);
        } else if (legsStep) {
            DrawOnePixelRect(DUCK_LEG_L_DOWN, x, oy, bodyColor);
            DrawOnePixelRect(DUCK_LEG_R_UP, x, oy, bodyColor);
        } else {
            DrawOnePixelRect(DUCK_LEG_L_DOWN, x, oy, bodyColor);
            DrawOnePixelRect(DUCK_LEG_R_DOWN, x, oy, bodyColor);
        }
        DrawOnePixelRect(DUCK_EYE, x, oy, eyeColor);
    } else {
        float oy = feetY - 20 * PIXEL;
        DrawPixelRects(DINO_BODY, 7, x, oy, bodyColor);
        if (legsStep && frame == 1) {
            DrawOnePixelRect(LEG_L_UP, x, oy, bodyColor);
            DrawOnePixelRect(LEG_R_DOWN, x, oy, bodyColor);
        } else if (legsStep) {
            DrawOnePixelRect(LEG_L_DOWN, x, oy, bodyColor);
            DrawOnePixelRect(LEG_R_UP, x, oy, bodyColor);
        } else {
            DrawOnePixelRect(LEG_L_DOWN, x, oy, bodyColor);
            DrawOnePixelRect(LEG_R_DOWN, x, oy, bodyColor);
        }
        DrawOnePixelRect(DINO_EYE, x, oy, eyeColor);
    }
}

/* Fills "out" with the dino's hitboxes and returns how many there are.
   The boxes are slightly smaller than the sprite so collisions feel fair. */
static int GetDinoHitboxes(Rectangle out[2])
{
    if (dino.ducking) {
        out[0] = (Rectangle){DINO_X + 4, dino.y - 20 + 4, 46, 14};
        return 1;
    }
    float top = dino.y - 20 * PIXEL;
    out[0] = (Rectangle){DINO_X + 24, top + 2, 14, 12};   /* head */
    out[1] = (Rectangle){DINO_X + 10, top + 16, 20, 20};  /* body */
    return 2;
}

static void ResetDino(void)
{
    dino.y = GROUND_Y;
    dino.velY = 0.0f;
    dino.onGround = true;
    dino.ducking = false;
    dino.alive = true;
    dino.runTimer = 0.0f;
    dino.frame = 0;
}

/* Handles keyboard input, jumping and gravity. */
static void UpdateDino(float dt, bool inputAllowed)
{
    bool jumpPressed = false, jumpHeld = false, duckHeld = false;
    if (inputAllowed) {
        jumpPressed = IsKeyPressed(KEY_SPACE) || IsKeyPressed(KEY_UP) || IsKeyPressed(KEY_W);
        jumpHeld = IsKeyDown(KEY_SPACE) || IsKeyDown(KEY_UP) || IsKeyDown(KEY_W);
        duckHeld = IsKeyDown(KEY_DOWN) || IsKeyDown(KEY_S);
    }

    /* A jump pressed up to 0.1 s before landing is remembered ("jump buffer"). */
    if (jumpPressed) jumpBuffer = 0.1f;
    else jumpBuffer -= dt;

    /* Jump only if standing on the ground => no double jumps in mid-air. */
    if (jumpBuffer > 0.0f && dino.onGround) {
        dino.velY = -JUMP_VELOCITY;
        dino.onGround = false;
        jumpBuffer = 0.0f;
        PlaySfx(sfxJump);
        SpawnParticles(DINO_X + 12, GROUND_Y - 2, 8, DustColor(), 90.0f, 0.6f, 2.0f);
    }

    dino.ducking = duckHeld && dino.onGround;

    if (!dino.onGround) {
        float gravity = GRAVITY;
        if (duckHeld) gravity *= FAST_FALL_FACTOR;               /* fast fall    */
        if (!jumpHeld && dino.velY < -JUMP_CUT_VELOCITY)         /* short hop    */
            dino.velY = -JUMP_CUT_VELOCITY;
        dino.velY += gravity * dt;                               /* gravity      */
        dino.y += dino.velY * dt;                                /* move         */
        if (dino.y >= GROUND_Y) {                                /* landed       */
            dino.y = GROUND_Y;
            dino.velY = 0.0f;
            dino.onGround = true;
            SpawnParticles(DINO_X + 14, GROUND_Y - 2, 6, DustColor(), 80.0f, 0.4f, 2.0f);
        }
    }

    /* Running animation: legs swap faster as the game speeds up. */
    dino.runTimer += dt * (gameSpeed / START_SPEED);
    dino.frame = ((int)(dino.runTimer / 0.1f)) % 2;

    /* Little puffs of dust behind the feet while running. */
    dustTimer -= dt;
    if (dino.onGround && dustTimer <= 0.0f) {
        dustTimer = 0.09f;
        SpawnParticles(DINO_X + 6, GROUND_Y - 2, 1, DustColor(), 40.0f, 0.5f, 2.0f);
    }
}

/* ========================================================================== */
/* 7. OBSTACLES                                                               */
/* ========================================================================== */

static void ClearObstacles(void)
{
    for (int i = 0; i < MAX_OBSTACLES; i++) obstacles[i].active = false;
}

static void SpawnObstacle(void)
{
    Obstacle *o = NULL;
    for (int i = 0; i < MAX_OBSTACLES; i++) {
        if (!obstacles[i].active) { o = &obstacles[i]; break; }
    }
    if (o == NULL) return; /* all slots busy: skip this spawn */

    memset(o, 0, sizeof(*o));
    o->active = true;
    o->x = VIRTUAL_W + 20.0f;

    int roll = GetRandomValue(0, 99);
    if (score >= 300.0f && roll < 25) {
        /* Bird at one of three heights above the ground:
           low  -> jump over it, middle -> duck under it, high -> just run. */
        static const float bottomOffsets[3] = {8.0f, 30.0f, 62.0f};
        o->type = OBST_BIRD;
        o->count = 1;
        o->w = 36.0f;
        o->h = 26.0f;
        o->y = GROUND_Y - bottomOffsets[GetRandomValue(0, 2)] - o->h;
    } else if (roll < 65) {
        o->type = OBST_CACTUS_SMALL;
        o->count = GetRandomValue(1, 3);
        o->h = 34.0f;
        o->w = o->count * 16.0f + (o->count - 1) * 4.0f;
        o->y = GROUND_Y - o->h;
    } else {
        o->type = OBST_CACTUS_LARGE;
        o->count = (score > 1500.0f) ? GetRandomValue(1, 3) : GetRandomValue(1, 2);
        o->h = 50.0f;
        o->w = o->count * 24.0f + (o->count - 1) * 4.0f;
        o->y = GROUND_Y - o->h;
    }
}

/* Distance (in pixels) to wait before the next obstacle. It scales with speed
   so there is always enough room to land and jump again. */
static float NextSpawnDistance(void)
{
    float minimum = gameSpeed * 0.70f + 80.0f;
    float extra = (GetRandomValue(0, 100) / 100.0f) * gameSpeed * 0.9f;
    return minimum + extra;
}

static void UpdateObstacles(float dt)
{
    spawnDistance -= gameSpeed * dt;
    if (spawnDistance <= 0.0f) {
        SpawnObstacle();
        spawnDistance = NextSpawnDistance();
    }

    for (int i = 0; i < MAX_OBSTACLES; i++) {
        Obstacle *o = &obstacles[i];
        if (!o->active) continue;
        float speed = gameSpeed + (o->type == OBST_BIRD ? BIRD_EXTRA_SPEED : 0.0f);
        o->x -= speed * dt;
        if (o->type == OBST_BIRD) {
            o->animTimer += dt;
            o->frame = ((int)(o->animTimer / 0.15f)) % 2;   /* flap wings */
        }
        if (o->x + o->w < -20.0f) o->active = false;        /* left the screen */
    }
}

static void DrawCactus(float x, float h, float w, Color c)
{
    float groundY = GROUND_Y;
    float trunkW = w * 0.40f;
    float trunkX = x + (w - trunkW) / 2.0f;
    float armT = fmaxf(4.0f, trunkW * 0.75f);        /* arm thickness */
    Color light = LerpColor(c, (Color){255, 255, 255, 255}, 0.25f);

    FillRect(trunkX, groundY - h, trunkW, h, c);                      /* trunk      */
    FillRect(trunkX + 2, groundY - h + 3, 2, h - 8, light);           /* highlight  */
    /* left arm: sideways piece + upward piece */
    FillRect(x, groundY - h * 0.50f, trunkX - x + 1, armT, c);
    FillRect(x, groundY - h * 0.50f - h * 0.28f, armT, h * 0.28f + armT, c);
    /* right arm, a little higher */
    FillRect(trunkX + trunkW - 1, groundY - h * 0.65f, x + w - (trunkX + trunkW) + 1, armT, c);
    FillRect(x + w - armT, groundY - h * 0.65f - h * 0.22f, armT, h * 0.22f + armT, c);
}

static void DrawBird(float x, float y, int frame, Color c)
{
    Color eye = Tint((Color){255, 255, 255, 255}, (Color){20, 20, 40, 255});
    FillRect(x, y + 11, 7, 3, c);            /* beak  */
    FillRect(x + 6, y + 8, 10, 8, c);        /* head  */
    FillRect(x + 12, y + 10, 22, 8, c);      /* body  */
    FillRect(x + 32, y + 9, 4, 4, c);        /* tail  */
    FillRect(x + 9, y + 10, 2, 2, eye);      /* eye   */
    if (frame == 0) {                        /* wings up */
        FillRect(x + 18, y + 0, 4, 10, c);
        FillRect(x + 22, y + 3, 6, 7, c);
    } else {                                 /* wings down */
        FillRect(x + 18, y + 18, 4, 8, c);
        FillRect(x + 22, y + 18, 6, 5, c);
    }
}

static void DrawObstacles(void)
{
    Color cactusColor = Tint((Color){34, 120, 62, 255}, (Color){90, 190, 130, 255});
    Color birdColor = Tint((Color){110, 55, 70, 255}, (Color){225, 175, 190, 255});

    for (int i = 0; i < MAX_OBSTACLES; i++) {
        const Obstacle *o = &obstacles[i];
        if (!o->active) continue;
        if (o->type == OBST_BIRD) {
            DrawBird(o->x, o->y, o->frame, birdColor);
        } else {
            float single = (o->type == OBST_CACTUS_SMALL) ? 16.0f : 24.0f;
            for (int k = 0; k < o->count; k++)
                DrawCactus(o->x + k * (single + 4.0f), o->h, single, cactusColor);
        }
    }
}

static Rectangle GetObstacleHitbox(const Obstacle *o)
{
    if (o->type == OBST_BIRD)
        return (Rectangle){o->x + 4, o->y + 6, o->w - 8, 14};
    return (Rectangle){o->x + 3, o->y + 3, o->w - 6, o->h - 3};
}

/* ========================================================================== */
/* 8. THE WORLD: SKY, CLOUDS, DUNES, GROUND, DAY AND NIGHT                    */
/* ========================================================================== */

static void InitWorld(void)
{
    for (int i = 0; i < MAX_CLOUDS; i++) {
        clouds[i].x = (float)GetRandomValue(0, VIRTUAL_W);
        clouds[i].y = (float)GetRandomValue(15, 110);
        clouds[i].speed = (float)GetRandomValue(8, 22);
        clouds[i].scale = GetRandomValue(8, 16) / 10.0f;
    }
    for (int i = 0; i < MAX_STARS; i++) {
        stars[i].x = (float)GetRandomValue(0, VIRTUAL_W);
        stars[i].y = (float)GetRandomValue(0, 150);
        stars[i].phase = (float)GetRandomValue(0, 628) / 100.0f;
        stars[i].size = GetRandomValue(1, 2);
    }
    for (int i = 0; i < MAX_SPECKS; i++) {
        specks[i].x = (float)GetRandomValue(0, VIRTUAL_W);
        specks[i].y = GROUND_Y + GetRandomValue(5, 55);
        specks[i].w = GetRandomValue(2, 10);
    }
    for (int i = 0; i < MAX_DECOR; i++) {
        decor[i].x = (float)GetRandomValue(0, VIRTUAL_W);
        decor[i].type = GetRandomValue(0, 3);
        decor[i].yOffset = GetRandomValue(10, 50);
    }
}

/* Slowly moves nightFactor toward day (0) or night (1). */
static void UpdateDayNight(float dt)
{
    float step = 0.35f * dt;
    if (nightFactor < nightTarget) nightFactor = fminf(nightFactor + step, nightTarget);
    else if (nightFactor > nightTarget) nightFactor = fmaxf(nightFactor - step, nightTarget);
}

/* Scrolls everything in the background. "scroll" is the ground speed. */
static void UpdateWorld(float dt, float scroll)
{
    bgScroll += scroll * dt;

    for (int i = 0; i < MAX_CLOUDS; i++) {
        clouds[i].x -= (clouds[i].speed + scroll * 0.05f) * dt;
        if (clouds[i].x < -100.0f) {
            clouds[i].x = VIRTUAL_W + (float)GetRandomValue(0, 120);
            clouds[i].y = (float)GetRandomValue(15, 110);
        }
    }
    for (int i = 0; i < MAX_SPECKS; i++) {
        specks[i].x -= scroll * dt;
        if (specks[i].x + specks[i].w < 0) {
            specks[i].x = VIRTUAL_W + (float)GetRandomValue(0, 40);
            specks[i].y = GROUND_Y + GetRandomValue(5, 55);
            specks[i].w = GetRandomValue(2, 10);
        }
    }
    for (int i = 0; i < MAX_DECOR; i++) {
        decor[i].x -= scroll * dt;
        if (decor[i].x < -30.0f) {
            decor[i].x = VIRTUAL_W + (float)GetRandomValue(0, 300);
            decor[i].type = GetRandomValue(0, 3);
            decor[i].yOffset = GetRandomValue(10, 50);
        }
    }
}

static void DrawCloud(float x, float y, float s, Color c)
{
    FillRect(x, y + 8 * s, 60 * s, 10 * s, c);
    FillRect(x + 8 * s, y + 3 * s, 26 * s, 8 * s, c);
    FillRect(x + 28 * s, y, 22 * s, 11 * s, c);
}

/* A row of rock/sand columns whose height follows a wavy curve (dunes). */
static void DrawDunes(float parallax, float base, float amp1, float amp2, float shift, Color c)
{
    float offset = bgScroll * parallax;
    for (int x = 0; x < VIRTUAL_W; x += 4) {
        float px = x + offset;
        float h = base + amp1 * sinf(px * 0.012f + shift) + amp2 * sinf(px * 0.031f + shift * 2.0f);
        FillRect((float)x, GROUND_Y - h, 4, h, c);
    }
}

static void DrawDecorItem(const Decor *d)
{
    float x = d->x;
    float y = GROUND_Y + d->yOffset;
    Color rock = Tint((Color){150, 120, 90, 255}, (Color){90, 85, 110, 255});
    Color plant = Tint((Color){90, 140, 70, 255}, (Color){60, 110, 90, 255});
    Color bone = Tint((Color){240, 230, 210, 255}, (Color){180, 180, 200, 255});

    switch (d->type) {
        case 0: /* rock */
            FillRect(x, y, 12, 6, rock);
            FillRect(x + 2, y - 3, 7, 3, rock);
            break;
        case 1: /* dry grass tuft */
            FillRect(x, y - 6, 2, 8, plant);
            FillRect(x + 4, y - 9, 2, 11, plant);
            FillRect(x + 8, y - 5, 2, 7, plant);
            break;
        case 2: /* tiny background cactus */
            FillRect(x + 3, y - 12, 4, 14, plant);
            FillRect(x, y - 8, 4, 3, plant);
            FillRect(x + 7, y - 10, 4, 3, plant);
            break;
        default: /* bone */
            FillRect(x, y, 14, 3, bone);
            FillRect(x - 2, y - 2, 4, 7, bone);
            FillRect(x + 12, y - 2, 4, 7, bone);
            break;
    }
}

static void DrawBackground(void)
{
    /* Sky: a gradient that fades between day and night colours. */
    Color skyTop = Tint((Color){120, 190, 235, 255}, (Color){10, 14, 44, 255});
    Color skyBottom = Tint((Color){255, 238, 205, 255}, (Color){52, 48, 105, 255});
    DrawRectangleGradientV(0, 0, VIRTUAL_W, GROUND_Y, skyTop, skyBottom);

    /* Stars (only visible at night, twinkling). */
    if (nightFactor > 0.02f) {
        double time = GetTime();
        for (int i = 0; i < MAX_STARS; i++) {
            float twinkle = 0.55f + 0.45f * sinf((float)time * 2.0f + stars[i].phase);
            FillRect(stars[i].x, stars[i].y, stars[i].size, stars[i].size,
                     Fade((Color){255, 255, 235, 255}, nightFactor * twinkle));
        }
    }

    /* Sun fades out while the moon fades in. */
    DrawCircle(640, 70, 22, Fade((Color){255, 214, 102, 255}, 1.0f - nightFactor));
    DrawCircle(640, 70, 17, Fade((Color){238, 238, 220, 255}, nightFactor));
    DrawCircle(634, 66, 4, Fade((Color){200, 200, 185, 255}, nightFactor));
    DrawCircle(646, 76, 3, Fade((Color){200, 200, 185, 255}, nightFactor));

    /* Clouds. */
    Color cloudColor = Tint((Color){255, 255, 255, 235}, (Color){70, 72, 125, 200});
    for (int i = 0; i < MAX_CLOUDS; i++) DrawCloud(clouds[i].x, clouds[i].y, clouds[i].scale, cloudColor);

    /* Two layers of distant dunes (they scroll slower = depth). */
    DrawDunes(0.10f, 34.0f, 18.0f, 8.0f, 0.0f,
              Tint((Color){236, 200, 150, 255}, (Color){40, 38, 78, 255}));
    DrawDunes(0.25f, 16.0f, 10.0f, 5.0f, 1.3f,
              Tint((Color){218, 172, 112, 255}, (Color){52, 48, 84, 255}));
}

static void DrawGround(void)
{
    Color sand = Tint((Color){226, 186, 124, 255}, (Color){72, 62, 82, 255});
    Color line = Tint((Color){120, 82, 50, 255}, (Color){150, 140, 170, 255});
    Color speck = Tint((Color){190, 148, 92, 255}, (Color){98, 86, 108, 255});

    FillRect(0, GROUND_Y, VIRTUAL_W, VIRTUAL_H - GROUND_Y, sand);
    FillRect(0, GROUND_Y, VIRTUAL_W, 2, line);

    for (int i = 0; i < MAX_SPECKS; i++)
        FillRect(specks[i].x, (float)specks[i].y, (float)specks[i].w, 2, speck);
    for (int i = 0; i < MAX_DECOR; i++) DrawDecorItem(&decor[i]);
}

