static Color UiTextColor(void)
{
    return Tint((Color){70, 50, 40, 255}, (Color){240, 240, 250, 255});
}

static void DrawButton(Rectangle r, const char *label, bool selected, float alpha)
{
    Color fill = selected ? (Color){255, 200, 60, 255} : (Color){28, 28, 46, 215};
    Color text = selected ? (Color){40, 25, 10, 255} : (Color){240, 240, 240, 255};
    DrawRectangleRec(r, Fade(fill, alpha));
    DrawRectangleLinesEx(r, 2.0f, Fade((Color){0, 0, 0, 255}, 0.8f * alpha));
    DrawTextCentered(label, (int)(r.x + r.width / 2), (int)(r.y + r.height / 2 - 10), 20, Fade(text, alpha));
}

static Rectangle MenuButtonRect(int i)
{
    return (Rectangle){310.0f, 112.0f + i * 36.0f, 180.0f, 30.0f};
}

static void DrawHud(void)
{
    char hiText[32];
    char curText[32];
    snprintf(hiText, sizeof(hiText), "HI %05d", settings.best);
    snprintf(curText, sizeof(curText), "%05d", (int)score);

    Color textColor = UiTextColor();
    Color dimColor = Fade(textColor, 0.6f);
    int curWidth = MeasureText(curText, 24);
    int hiWidth = MeasureText(hiText, 24);
    int curX = VIRTUAL_W - 20 - curWidth;

    DrawText(hiText, curX - 24 - hiWidth, 14, 24, dimColor);

    /* After a milestone the score blinks for a moment. */
    bool visible = !(flashTimer > 0.0f && ((int)(flashTimer * 8.0f)) % 2 == 0);
    if (visible) DrawText(curText, curX, 14, 24, textColor);

    if (bonusTimer > 0.0f)
        DrawText("+25 BONUS!", curX - 40, 42, 16, Fade((Color){255, 160, 20, 255}, ClampFloat(bonusTimer, 0.0f, 1.0f)));

    DrawText(settings.soundOn ? "SOUND ON  (M)" : "SOUND OFF (M)", 14, 14, 12, dimColor);
    DrawText("PAUSE (P)", 14, 30, 12, dimColor);
}

static void DrawMenu(void)
{
    Color title = Tint((Color){70, 40, 30, 255}, (Color){255, 220, 120, 255});
    float bounce = sinf((float)GetTime() * 3.0f) * 3.0f;

    DrawTextCentered("DINO RUNNER", VIRTUAL_W / 2 + 3, (int)(20 + bounce + 3), 56, Fade((Color){0, 0, 0, 255}, 0.25f));
    DrawTextCentered("DINO RUNNER", VIRTUAL_W / 2, (int)(20 + bounce), 56, title);

    if (((int)(GetTime() * 2.0)) % 2 == 0)
        DrawTextCentered("Press SPACE to start", VIRTUAL_W / 2, 84, 18, UiTextColor());

    char best[32];
    snprintf(best, sizeof(best), "BEST %05d", settings.best);
    DrawText(best, VIRTUAL_W - 20 - MeasureText(best, 20), 14, 20, UiTextColor());

    const char *labels[3] = {"PLAY", "SETTINGS", "QUIT"};
    for (int i = 0; i < 3; i++) DrawButton(MenuButtonRect(i), labels[i], menuSelection == i, 1.0f);

    Color info = Tint((Color){90, 55, 25, 255}, (Color){215, 215, 235, 255});
    DrawTextCentered("SPACE / UP : jump      DOWN : duck      P : pause", VIRTUAL_W / 2, 244, 16, info);
    DrawTextCentered("M : sound on/off      F : fullscreen      ESC : quit", VIRTUAL_W / 2, 268, 16, info);
}

static void BuildVolumeBar(char *out, size_t size, int value)
{
    char bar[16];
    for (int i = 0; i < 10; i++) bar[i] = (i < value) ? '|' : '.';
    bar[10] = '\0';
    snprintf(out, size, "[%s] %2d", bar, value);
}

