/* ========================================================================== */
/* 10. GAME STATES AND MAIN LOOP                                              */
/* ========================================================================== */

/* Puts everything back to its starting values for a fresh run. */
static void ResetGame(void)
{
    score = 0.0f;
    gameSpeed = START_SPEED;
    spawnDistance = 250.0f;
    lastMilestone = 0;
    jumpBuffer = 0.0f;
    dustTimer = 0.0f;
    newBest = false;
    gameOverTimer = 0.0f;
    flashTimer = 0.0f;
    bonusTimer = 0.0f;
    shakeTimer = 0.0f;
    hitFlash = 0.0f;
    ClearObstacles();
    for (int i = 0; i < MAX_PARTICLES; i++) particles[i].active = false;
    ResetDino();
}

/* Starts a fade-out; when the screen is black the state switches, then fades in. */
static void ChangeState(GameState next)
{
    if (transPhase != TRANS_NONE) return;
    pendingState = next;
    transPhase = TRANS_OUT;
}

static void UpdateTransition(float dt)
{
    if (transPhase == TRANS_OUT) {
        transAlpha += dt / 0.18f;
        if (transAlpha >= 1.0f) {
            transAlpha = 1.0f;
            gameState = pendingState;
            if (gameState == STATE_PLAYING) ResetGame();
            if (gameState == STATE_MENU) { ResetDino(); menuSelection = 0; }
            if (gameState == STATE_SETTINGS) settingsSelection = 0;
            transPhase = TRANS_IN;
        }
    } else if (transPhase == TRANS_IN) {
        transAlpha -= dt / 0.18f;
        if (transAlpha <= 0.0f) {
            transAlpha = 0.0f;
            transPhase = TRANS_NONE;
        }
    }
}

static void ToggleSound(void)
{
    settings.soundOn = !settings.soundOn;
    SaveGameData();
}

/* Keys that work on every screen. */
static void HandleGlobalKeys(bool locked)
{
    if (locked) return;
    if (IsKeyPressed(KEY_M)) ToggleSound();
    bool altEnter = IsKeyPressed(KEY_ENTER) && (IsKeyDown(KEY_LEFT_ALT) || IsKeyDown(KEY_RIGHT_ALT));
    if (IsKeyPressed(KEY_F11) || IsKeyPressed(KEY_F) || altEnter) ToggleFullscreen();
}

/* The dino hit something: switch to the game-over state. */
static void KillDino(void)
{
    dino.alive = false;
    gameState = STATE_GAMEOVER;
    gameOverTimer = 0.0f;
    shakeTimer = 0.3f;
    hitFlash = 0.35f;
    PlaySfx(sfxHit);
    SpawnParticles(DINO_X + 20, dino.y - 20, 40, Tint((Color){70, 70, 85, 255}, (Color){230, 230, 245, 255}), 260.0f, 1.0f, 3.0f);
    SpawnParticles(DINO_X + 20, dino.y - 20, 15, (Color){255, 170, 40, 255}, 220.0f, 1.0f, 3.0f);

    int finalScore = (int)score;
    if (finalScore > settings.best) {
        settings.best = finalScore;
        newBest = true;
        SaveGameData();
    }
}

static void CheckCollisions(void)
{
    Rectangle boxes[2];
    int boxCount = GetDinoHitboxes(boxes);
    for (int i = 0; i < MAX_OBSTACLES; i++) {
        if (!obstacles[i].active) continue;
        Rectangle ob = GetObstacleHitbox(&obstacles[i]);
        for (int b = 0; b < boxCount; b++) {
            if (CheckCollisionRecs(boxes[b], ob)) {
                KillDino();
                return;
            }
        }
    }
}

static void UpdateEffects(float dt)
{
    if (flashTimer > 0.0f) flashTimer -= dt;
    if (bonusTimer > 0.0f) bonusTimer -= dt;
    if (shakeTimer > 0.0f) shakeTimer -= dt;
    if (hitFlash > 0.0f) hitFlash -= dt;
    if (resetMessageTimer > 0.0f) resetMessageTimer -= dt;
}

static void UpdateMenu(float dt, bool locked)
{
    nightTarget = 0.0f;
    UpdateDayNight(dt);
    UpdateWorld(dt, 140.0f);
    UpdateParticles(dt);

    /* The dino jogs on the spot in the menu. */
    menuRunTimer += dt;
    dino.frame = ((int)(menuRunTimer / 0.12f)) % 2;

    if (locked) return;

    if (IsKeyPressed(KEY_DOWN) || IsKeyPressed(KEY_S)) { menuSelection = (menuSelection + 1) % 3; PlaySfx(sfxClick); }
    if (IsKeyPressed(KEY_UP) || IsKeyPressed(KEY_W)) { menuSelection = (menuSelection + 2) % 3; PlaySfx(sfxClick); }

    /* Mouse: hovering selects, clicking activates. */
    Vector2 mouse = GetVirtualMouse();
    Vector2 delta = GetMouseDelta();
    bool clicked = false;
    for (int i = 0; i < 3; i++) {
        if (CheckCollisionPointRec(mouse, MenuButtonRect(i))) {
            if (delta.x != 0.0f || delta.y != 0.0f) menuSelection = i;
            if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) { menuSelection = i; clicked = true; }
        }
    }

    if (IsKeyPressed(KEY_SPACE)) {                   /* SPACE always starts the game */
        PlaySfx(sfxClick);
        ChangeState(STATE_PLAYING);
    } else if (IsKeyPressed(KEY_ENTER) || clicked) { /* ENTER / click uses the selected button */
        PlaySfx(sfxClick);
        if (menuSelection == 0) ChangeState(STATE_PLAYING);
        else if (menuSelection == 1) ChangeState(STATE_SETTINGS);
        else quitRequested = true;
    } else if (IsKeyPressed(KEY_ESCAPE)) {
        quitRequested = true;
    }
}

/* Change one setting row. dir: -1 = left, +1 = right, 0 = ENTER / click. */
static void AdjustSetting(int index, int dir)
{
    switch (index) {
        case 0:
            ToggleSound();
            break;
        case 1:
            settings.musicVolume = (dir == 0) ? (settings.musicVolume + 1) % 11
                                              : ClampInt(settings.musicVolume + dir, 0, 10);
            ApplyAudioVolumes();
            SaveGameData();
            break;
        case 2:
            settings.sfxVolume = (dir == 0) ? (settings.sfxVolume + 1) % 11
                                            : ClampInt(settings.sfxVolume + dir, 0, 10);
            ApplyAudioVolumes();
            SaveGameData();
            PlaySfx(sfxClick);
            break;
        case 3:
            ToggleFullscreen();
            break;
        case 4:
            if (dir == 0) {
                settings.best = 0;
                SaveGameData();
                resetMessageTimer = 1.5f;
            }
            break;
        default:
            if (dir == 0) ChangeState(STATE_MENU);
            break;
    }
}

static void UpdateSettings(float dt, bool locked)
{
    nightTarget = 0.0f;
    UpdateDayNight(dt);
    UpdateWorld(dt, 140.0f);
    menuRunTimer += dt;
    dino.frame = ((int)(menuRunTimer / 0.12f)) % 2;

    if (locked) return;

    if (IsKeyPressed(KEY_DOWN) || IsKeyPressed(KEY_S)) { settingsSelection = (settingsSelection + 1) % 6; PlaySfx(sfxClick); }
    if (IsKeyPressed(KEY_UP) || IsKeyPressed(KEY_W)) { settingsSelection = (settingsSelection + 5) % 6; PlaySfx(sfxClick); }
    if (IsKeyPressed(KEY_LEFT)) AdjustSetting(settingsSelection, -1);
    if (IsKeyPressed(KEY_RIGHT)) AdjustSetting(settingsSelection, +1);
    if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE)) { PlaySfx(sfxClick); AdjustSetting(settingsSelection, 0); }

    /* Mouse support for the rows. */
    Vector2 mouse = GetVirtualMouse();
    for (int i = 0; i < 6; i++) {
        Rectangle row = {156.0f, 69.0f + i * 29.0f, 488.0f, 26.0f};
        if (CheckCollisionPointRec(mouse, row) && IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) {
            settingsSelection = i;
            PlaySfx(sfxClick);
            AdjustSetting(i, 0);
        }
    }

    if (IsKeyPressed(KEY_ESCAPE)) { PlaySfx(sfxClick); ChangeState(STATE_MENU); }
}

static void UpdatePlaying(float dt, bool locked)
{
    /* Pause with P, ESC, or automatically if the window loses focus. */
    if (!locked && (IsKeyPressed(KEY_P) || IsKeyPressed(KEY_ESCAPE) || !IsWindowFocused())) {
        gameState = STATE_PAUSED;
        PlaySfx(sfxClick);
        return;
    }

    /* Score grows with distance travelled; speed grows with score. */
    score += gameSpeed * dt * 0.04f;
    gameSpeed = fminf(MAX_SPEED, START_SPEED + score * 0.28f);

    /* Day <-> night every NIGHT_INTERVAL points. */
    nightTarget = (((int)score / NIGHT_INTERVAL) % 2 == 1) ? 1.0f : 0.0f;
    UpdateDayNight(dt);

    UpdateWorld(dt, gameSpeed);
    UpdateDino(dt, !locked);
    UpdateObstacles(dt);
    UpdateParticles(dt);

    /* Milestones: a sound and blinking every 100 points, +25 bonus every 500. */
    int milestone = (int)score / 100;
    if (milestone > lastMilestone) {
        lastMilestone = milestone;
        PlaySfx(sfxMilestone);
        flashTimer = 1.0f;
        if (milestone % 5 == 0) {
            score += 25.0f;
            bonusTimer = 1.2f;
        }
    }

    CheckCollisions();
}

static void UpdatePaused(bool locked)
{
    if (locked) return;
    if (IsKeyPressed(KEY_P)) {
        gameState = STATE_PLAYING;
        PlaySfx(sfxClick);
    } else if (IsKeyPressed(KEY_ESCAPE)) {
        PlaySfx(sfxClick);
        ChangeState(STATE_MENU);
    }
}

static void UpdateGameOver(float dt, bool locked)
{
    gameOverTimer += dt;
    UpdateParticles(dt);
    if (locked || gameOverTimer < 0.4f) return; /* short delay avoids accidental restarts */

    Vector2 mouse = GetVirtualMouse();
    bool clickRestart = IsMouseButtonPressed(MOUSE_BUTTON_LEFT) && CheckCollisionPointRec(mouse, GameOverButtonRect(0));
    bool clickMenu = IsMouseButtonPressed(MOUSE_BUTTON_LEFT) && CheckCollisionPointRec(mouse, GameOverButtonRect(1));

    if (IsKeyPressed(KEY_SPACE) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_UP) || clickRestart) {
        PlaySfx(sfxClick);
        ChangeState(STATE_PLAYING);   /* ResetGame() runs while the screen is black */
    } else if (IsKeyPressed(KEY_ESCAPE) || clickMenu) {
        PlaySfx(sfxClick);
        ChangeState(STATE_MENU);
    }
}

static void UpdateGame(float dt)
{
    UpdateTransition(dt);
    bool locked = (transPhase != TRANS_NONE);

    HandleGlobalKeys(locked);
    UpdateEffects(dt);

    switch (gameState) {
        case STATE_MENU:     UpdateMenu(dt, locked); break;
        case STATE_SETTINGS: UpdateSettings(dt, locked); break;
        case STATE_PLAYING:  UpdatePlaying(dt, locked); break;
        case STATE_PAUSED:   UpdatePaused(locked); break;
        case STATE_GAMEOVER: UpdateGameOver(dt, locked); break;
    }
    UpdateMusic();
}

static void DrawGame(void)
{
    ClearBackground((Color){0, 0, 0, 255});

    /* Screen shake: the whole world is drawn with a small random offset. */
    Camera2D camera = {0};
    camera.zoom = 1.0f;
    if (shakeTimer > 0.0f) {
        camera.offset = (Vector2){(float)GetRandomValue(-5, 5), (float)GetRandomValue(-5, 5)};
    }

    BeginMode2D(camera);
    DrawBackground();
    DrawGround();
    DrawObstacles();

    bool menuLike = (gameState == STATE_MENU || gameState == STATE_SETTINGS);
    if (menuLike) {
        DrawDino(DINO_X, GROUND_Y, false, true, true, dino.frame);
    } else {
        DrawDino(DINO_X, dino.y, dino.ducking, dino.onGround, dino.alive, dino.frame);
    }
    DrawParticles();
    EndMode2D();

    if (hitFlash > 0.0f)
        DrawRectangle(0, 0, VIRTUAL_W, VIRTUAL_H, Fade((Color){255, 255, 255, 255}, ClampFloat(hitFlash / 0.35f, 0.0f, 1.0f) * 0.6f));

    switch (gameState) {
        case STATE_MENU:     DrawMenu(); break;
        case STATE_SETTINGS: DrawSettings(); break;
        case STATE_PLAYING:  DrawHud(); break;
        case STATE_PAUSED:   DrawHud(); DrawPauseOverlay(); break;
        case STATE_GAMEOVER: DrawHud(); DrawGameOverOverlay(); break;
    }

    /* Fade to black during screen transitions. */
    if (transAlpha > 0.0f)
        DrawRectangle(0, 0, VIRTUAL_W, VIRTUAL_H, Fade((Color){0, 0, 0, 255}, transAlpha));
}

int main(void)
{
    /* --- create the window --- */
    SetConfigFlags(FLAG_WINDOW_RESIZABLE | FLAG_VSYNC_HINT);
    InitWindow(960, 360, "Dino Runner");
    SetWindowMinSize(400, 150);
    SetExitKey(KEY_NULL);            /* ESC is used by the game, not to close it */
    SetTargetFPS(60);
    SetRandomSeed((unsigned int)time(NULL));
    srand((unsigned int)time(NULL));

    /* The save file lives next to the .exe. */
    snprintf(saveFilePath, sizeof(saveFilePath), "%s%s", GetApplicationDirectory(), SAVE_FILE_NAME);
    LoadGameData();

    /* --- audio (the game still works silently if there is no sound device) --- */
    InitAudioDevice();
    audioReady = IsAudioDeviceReady();
    if (audioReady) {
        GenerateAudio();
        ApplyAudioVolumes();
    }

    /* --- off-screen canvas that we draw the game on --- */
    renderTarget = LoadRenderTexture(VIRTUAL_W, VIRTUAL_H);
    SetTextureFilter(renderTarget.texture, TEXTURE_FILTER_BILINEAR);

    InitWorld();
    ResetGame();

    /* --- the game loop: runs once per frame until the window closes --- */
    while (!WindowShouldClose() && !quitRequested) {
        float dt = fminf(GetFrameTime(), 0.05f);  /* cap dt so a lag spike can't break physics */

        /* Work out how the virtual screen fits into the real window (letterboxing). */
        float sw = (float)GetScreenWidth();
        float sh = (float)GetScreenHeight();
        viewScale = fminf(sw / VIRTUAL_W, sh / VIRTUAL_H);
        viewOffsetX = (sw - VIRTUAL_W * viewScale) / 2.0f;
        viewOffsetY = (sh - VIRTUAL_H * viewScale) / 2.0f;

        UpdateGame(dt);

        BeginTextureMode(renderTarget);
        DrawGame();
        EndTextureMode();

        BeginDrawing();
        ClearBackground((Color){0, 0, 0, 255});
        /* The negative height flips the image (render textures are upside down). */
        DrawTexturePro(renderTarget.texture,
                       (Rectangle){0, 0, (float)VIRTUAL_W, -(float)VIRTUAL_H},
                       (Rectangle){viewOffsetX, viewOffsetY, VIRTUAL_W * viewScale, VIRTUAL_H * viewScale},
                       (Vector2){0, 0}, 0.0f, (Color){255, 255, 255, 255});
        EndDrawing();
    }

    /* --- clean up everything we created --- */
    SaveGameData();
    if (audioReady) {
        UnloadSound(sfxJump);
        UnloadSound(sfxHit);
        UnloadSound(sfxMilestone);
        UnloadSound(sfxClick);
        UnloadSound(musicLoop);
    }
    UnloadRenderTexture(renderTarget);
    CloseAudioDevice();
    CloseWindow();
    return 0;
}
